package app.flare.auto;
import android.app.Activity;import android.content.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;

final class UiKit {
 final Activity a;ThemeTokens t; enum Role{PRIMARY,SECONDARY,ACCENT,GROUP,DIVIDER}UiKit(Activity a){this.a=a;t=ThemeTokens.get(a);}int dp(int v){return (int)(v*a.getResources().getDisplayMetrics().density+.5f);}
 TextView text(String s,int size,int color){TextView v=new TextView(a);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setTag(color==t.accent?Role.ACCENT:color==t.textSecondary?Role.SECONDARY:Role.PRIMARY);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 LinearLayout column(){LinearLayout c=new LinearLayout(a);c.setOrientation(LinearLayout.VERTICAL);return c;}
 LinearLayout header(String title){LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);TextView back=text("‹",28,t.textPrimary);back.setGravity(Gravity.CENTER);back.setContentDescription("Back");row.addView(back,new LinearLayout.LayoutParams(dp(56),dp(56)));back.setOnClickListener(v->a.finish());TextView label=text(title,20,t.textPrimary);label.setTypeface(Typeface.DEFAULT,Typeface.BOLD);row.addView(label,new LinearLayout.LayoutParams(0,dp(56),1));TextView home=text("⌂",25,t.textPrimary);home.setGravity(Gravity.CENTER);home.setContentDescription("Home");row.addView(home,new LinearLayout.LayoutParams(dp(56),dp(56)));home.setOnClickListener(v->{Intent i=new Intent(a,HomeActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);a.startActivity(i);a.finish();});return row;}
 TextView section(String s){TextView h=text(s,13,t.accent);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.setPadding(dp(8),dp(16),dp(8),dp(8));return h;}
 LinearLayout group(){LinearLayout g=column();g.setBackground(new GlassDrawable(t.card,dp(12),t.cardBorder));g.setTag(Role.GROUP);return g;}
 View divider(){View v=new View(a);v.setBackgroundColor(t.cardBorder);v.setTag(Role.DIVIDER);return v;}
 void add(LinearLayout group,View row){if(group.getChildCount()>0){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.leftMargin=dp(16);p.rightMargin=dp(16);group.addView(divider(),p);}group.addView(row,new LinearLayout.LayoutParams(-1,-2));}
 LinearLayout valueRow(String title,String value,Runnable action){LinearLayout r=new LinearLayout(a);r.setGravity(Gravity.CENTER_VERTICAL);r.setMinimumHeight(dp(56));r.setPadding(dp(16),0,dp(16),0);TextView left=text(title,16,t.textPrimary);left.setMaxLines(2);r.addView(left,new LinearLayout.LayoutParams(0,-2,1));TextView right=text(value,14,t.textSecondary);right.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);right.setMaxLines(2);r.addView(right,new LinearLayout.LayoutParams(-2,-2));if(action!=null)r.setOnClickListener(v->action.run());return r;}
 void recolor(View root){t=ThemeTokens.get(a);a.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(t.background));root.setBackgroundColor(t.background);recolorTree(root);}
 void recolorTree(View v){Object tag=v.getTag();if(tag==Role.GROUP)v.setBackground(new GlassDrawable(t.card,dp(12),t.cardBorder));else if(tag==Role.DIVIDER)v.setBackgroundColor(t.cardBorder);else if(v instanceof TextView){TextView text=(TextView)v;if(tag==Role.PRIMARY)text.setTextColor(t.textPrimary);else if(tag==Role.SECONDARY)text.setTextColor(t.textSecondary);else if(tag==Role.ACCENT)text.setTextColor(t.accent);}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)recolorTree(g.getChildAt(i));}}
 LinearLayout toggle(String title,boolean value,Runnable action){return valueRow(title,value?"On":"Off",action);}
 LinearLayout stepper(String title,String value,Runnable minus,Runnable plus){LinearLayout row=valueRow(title,"",null);TextView neg=text("−",24,t.textPrimary);neg.setGravity(Gravity.CENTER);neg.setContentDescription("Decrease "+title);row.addView(neg,new LinearLayout.LayoutParams(dp(56),dp(56)));neg.setOnClickListener(v->minus.run());TextView val=text(value,14,t.textSecondary);val.setGravity(Gravity.CENTER);row.addView(val,new LinearLayout.LayoutParams(dp(44),dp(56)));TextView pos=text("+",24,t.textPrimary);pos.setGravity(Gravity.CENTER);pos.setContentDescription("Increase "+title);row.addView(pos,new LinearLayout.LayoutParams(dp(56),dp(56)));pos.setOnClickListener(v->plus.run());return row;}
}
